# frozen_string_literal: true

module MaintenanceTasks
  module Types
    # An Active Model type for attributes containing a list of strings.
    #
    # Values submitted by a multiple select are cast to strings, and blank
    # values generated by Rails' hidden input are removed.
    class StringList < ActiveModel::Type::Value
      private

      def cast_value(value)
        values = value.is_a?(Array) ? value : [value]
        values.reject { |item| item.nil? || item == "" }.map(&:to_s)
      end
    end
  end
end
